import { createConnection } from "node:net";
import { lstat } from "node:fs/promises";
import { isAbsolute } from "node:path";
import { pathToFileURL } from "node:url";

/** No provider/configuration environment is read or forwarded. Unix stream only. */
export async function runBridge(path: string): Promise<void> {
  const stat = await lstat(path);
  if (!isAbsolute(path) || !stat.isSocket() || (stat.mode & 0o077) !== 0 || stat.uid !== process.getuid?.()) throw new Error("untrusted_socket");
  await new Promise<void>((resolve, reject) => {
    const socket = createConnection(path);
    const timer = setTimeout(() => socket.destroy(new Error("connect_timeout")), 5000);
    const stop = () => socket.destroy();
    process.once("SIGTERM", stop); process.once("SIGINT", stop);
    socket.once("connect", () => { clearTimeout(timer); process.stdin.pipe(socket); socket.pipe(process.stdout); });
    socket.once("error", () => reject(new Error("research_disconnected")));
    process.stdin.once("error", stop); process.stdout.once("error", stop);
    socket.once("close", () => {
      clearTimeout(timer); process.stdin.unpipe(socket); process.stdin.pause();
      process.removeListener("SIGTERM", stop); process.removeListener("SIGINT", stop);
      process.stdin.removeListener("error", stop); process.stdout.removeListener("error", stop); resolve();
    });
  });
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    if (process.argv.length !== 3) throw new Error("usage");
    await runBridge(process.argv[2]);
  } catch { process.stderr.write("research_bridge_unavailable\n"); process.exitCode = 1; }
}

