import { createReadStream } from "node:fs";
import { pathToFileURL } from "node:url";
import { createHash } from "node:crypto";
import { ResearchService, type TrustedResearchHost } from "../core/service.js";
import { ResearchEngine } from "../core/engine.js";
import { BraveSearchAdapter } from "../core/brave.js";
import { VolatileWorkLedger, type Work } from "../core/work.js";
import type { CorePolicy } from "../core/contracts.js";
import { fixtureHost, fixtureProvider, fixtureTransport } from "../core/fixture.js";
import { resolveSourcePolicy } from "../core/policy.js";
import { startSidecar } from "./sidecar.js";
import { MCP_RELEASE } from "./protocol.js";

let startupPhase = "arguments";

/** Private inherited setup descriptors; never stdin, argv, workspace config or env secrets. */
async function descriptor(fd: number, maximum: number): Promise<string> {
  const stream = createReadStream("", { fd, autoClose: true });
  const timer = setTimeout(() => stream.destroy(new Error("setup_timeout")), 5000);
  const chunks: Buffer[] = []; let length = 0;
  try {
    for await (const chunk of stream) {
      length += chunk.length;
      if (length > maximum) throw new Error("setup_oversized");
      chunks.push(chunk);
    }
    return new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks));
  } finally { clearTimeout(timer); stream.destroy(); }
}
export async function runSidecar(): Promise<void> {
  const args = process.argv.slice(2);
  const takeFlag = (flag: string): boolean => {
    const matches = args.reduce<number[]>((found, value, index) => value === flag ? [...found, index] : found, []);
    if (matches.length > 1) throw new Error("duplicate_source_or_fixture_option");
    if (matches.length === 0) return false;
    args.splice(matches[0]!, 1); return true;
  };
  const fixture = takeFlag("--fixture");
  const githubExcluded = takeFlag("--github-excluded");
  const requestedSourcePolicy = githubExcluded ? "github-excluded-v1" : "public-web-v1";
  if (args.length !== 2 || args[0] !== "--directory") throw new Error("usage");
  const lifecycle = new AbortController();
  let host: TrustedResearchHost, engine: ResearchEngine;
  if (fixture) {
    startupPhase = "fixture_host";
    const base = fixtureHost();
    host = { ...base, policy: githubExcluded
      ? resolveSourcePolicy({ ...base.policy, sourcePolicy: undefined, semanticHash: base.policy.baseSemanticHash! }, requestedSourcePolicy)
      : base.policy };
    engine = new ResearchEngine(fixtureProvider, fixtureTransport(), host.now);
  } else {
    startupPhase = "trusted_setup";
    const setup = JSON.parse(await descriptor(3, 16384)) as { contractVersion: number; sessionId: string; capabilityIdentity: string; cacheNamespace: string; policy: CorePolicy; limits: Work };
    if (!setup || setup.contractVersion !== 1 || Object.keys(setup).some(k => !["contractVersion", "sessionId", "capabilityIdentity", "cacheNamespace", "policy", "limits"].includes(k))) throw new Error("invalid_setup");
    const ledger = new VolatileWorkLedger(setup.limits);
    const policy = resolveSourcePolicy(setup.policy, requestedSourcePolicy);
    host = { ...setup, policy, ledger, callLimit: ledger.limit("calls")!, signal: lifecycle.signal, now: () => new Date(),
      authorize: async () => true,
      record: async (callId, evidence) => { process.stderr.write(JSON.stringify({ type: "research_evidence", callId, evidence }) + "\n"); } };
    startupPhase = "credential";
    const credential = (await descriptor(4, 4096)).trim();
    engine = new ResearchEngine(new BraveSearchAdapter(credential), undefined, host.now, [credential]);
  }
  startupPhase = "sidecar";
  const service = new ResearchService(engine, host);
  const sidecar = await startSidecar(args[1], service);
  process.stdout.write(JSON.stringify({ type: "ready", release: MCP_RELEASE, fixture, durability: "volatile",
    policy: { id: host.policy.policyId, version: host.policy.version, hash: host.policy.semanticHash },
    sourcePolicy: { requestedProfileId: requestedSourcePolicy, effective: host.policy.sourcePolicy },
    setupDigest: createHash("sha256").update(JSON.stringify({ sessionId: host.sessionId, capabilityIdentity: host.capabilityIdentity,
      cacheNamespace: host.cacheNamespace, policy: host.policy, limits: Object.fromEntries(["calls", "providerAttempts", "fetchedDocuments", "fetchedBytes", "scoringPairs", "scoringWindows", "scoringTokens", "elapsedMs"].map(k => [k, host.ledger.limit(k as keyof Work)])) })).digest("hex") }) + "\n");
  await new Promise<void>(resolve => {
    const stop = () => { lifecycle.abort(); void sidecar.close().then(resolve); };
    process.once("SIGINT", stop); process.once("SIGTERM", stop);
  });
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try { await runSidecar(); }
  catch (error) {
    const diagnostic = error instanceof Error && [
      "duplicate_source_or_fixture_option", "usage", "invalid_setup", "setup_timeout", "setup_oversized",
      "source policy profile is unavailable", "source policy profile mismatch", "source policy semantic hash mismatch",
    ].includes(error.message) ? `: ${error.message}`
      : error instanceof Error && "code" in error && ["EACCES", "EADDRINUSE", "ENOENT", "EPERM"].includes(String(error.code))
        ? `: ${String(error.code)}` : "";
    process.stderr.write(`research_sidecar_unavailable_or_trial_already_started:${startupPhase}${diagnostic}\n`);
    process.exitCode = 1;
  }
}
import { createServer, type Socket } from "node:net";
import { lstat, open, chmod, unlink } from "node:fs/promises";
import { join, isAbsolute } from "node:path";
import type { ResearchService } from "../core/service.js";
import { attachResearchMcp } from "./protocol.js";

/** The socket mount is the session capability; the supervisor alone selects its service. */
export async function startSidecar(directory: string, service: ResearchService) {
  const stat = await lstat(directory);
  if (!isAbsolute(directory) || !stat.isDirectory() || stat.isSymbolicLink() || (stat.mode & 0o077) !== 0 || stat.uid !== process.getuid?.()) {
    throw new Error("private_directory_required");
  }
  const path = join(directory, "research.sock");
  if (Buffer.byteLength(path) > 100) throw new Error("socket_path_too_long");
  // Never erase this guard on shutdown: volatile accounting cannot recover a trial.
  const marker = await open(join(directory, "started"), "wx", 0o600);
  try { await marker.writeFile("volatile-trial-started-v1\n"); await marker.sync(); }
  finally { await marker.close(); }
  const sockets = new Set<Socket>();
  const server = createServer(socket => {
    if (sockets.size >= 4) { socket.destroy(); return; }
    sockets.add(socket); socket.once("close", () => sockets.delete(socket));
    attachResearchMcp(socket, service);
  });
  try {
    await new Promise<void>((resolve, reject) => { server.once("error", reject); server.listen(path, resolve); });
    await chmod(path, 0o600);
  } catch (error) {
    service.close(); for (const socket of sockets) socket.destroy();
    if (server.listening) await new Promise<void>(resolve => server.close(() => resolve()));
    throw error;
  }
  let closed = false;
  return { path, async close() {
    if (closed) return; closed = true;
    service.close(); for (const socket of sockets) socket.destroy();
    await new Promise<void>(resolve => server.close(() => resolve()));
    await unlink(path).catch(error => { if (error.code !== "ENOENT") throw error; });
  } };
}
# RelayView research MCP 1.1.0

Thin MCP stdio bridge and supervised Unix-socket service over the shared
`@relayview/research-core` 1.1.0 source, selection `lexical-v2-initial-4`.
The tarball includes that exact compiled source, parse5 8.0.1 and saxes 6.0.0
through its shrinkwrap. It does not contain a second ranker or import the owner.

Use Node 22.19–22.x or 24.11–24.x on Linux. Build with `npm run build`, inspect
`npm run artifact`, and pack with `npm pack`. Run the credential-free transport
check with `node dist/mcp/smoke.js` (requires Bubblewrap). The fixture calls a
supervised service through a network-disabled stdio bridge.

With no source option, the launcher derives `public-web-v1` and GitHub remains
allowed. Add `--github-excluded` to derive `github-excluded-v1`. Readiness reports
both the requested profile and its complete effective descriptor; duplicated,
unknown, or requested/effective mismatches fail startup.

Trusted launch: `node dist/mcp/main.js --directory /absolute/private/trial-dir`.
Supply the version-1 trusted session/policy/limits JSON over inherited descriptor
3 and the Brave credential over inherited descriptor 4, then close both writers.
Neither value is accepted over MCP, argv, or ordinary environment variables.
For an explicitly disposable fixture, add `--fixture` before `--directory`.
For the GitHub-excluded profile, add `--github-excluded` before `--directory`.

Client command: `node dist/mcp/bridge.js /absolute/private/trial-dir/research.sock`.
Only `web_search` and `web_fetch` are exposed. Core requests, canonical results,
accounting and private-address rules retain their shared meaning. Responses have
one JSON text block and no `structuredContent` duplicate.

The private socket mount is the session capability. The trusted supervisor must
isolate each trial's filesystem/mount namespace, prevent agent edits to client
configuration and binaries, and hide all other session sockets, credential and
control paths. A same-UID unrestricted shell is outside that boundary. Do not
present socket file modes as protection from the same unrestricted user.

This standalone host uses volatile accounting and keeps a `started` marker.
Bridge reconnect preserves the live service allowance. Service restart in the
same directory is refused; do not delete the marker to resume a trial. Durable
benchmark provisioning/accounting is separate integration work. Stop the whole
trial on sidecar loss; only a newly authorized trial may receive fresh state.

The repository's `docs/authoritative/research-mcp.md` contains complete setup,
pinned native verification, live smoke, recovery, cleanup and evidence limits.

