import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { mkdtemp, rm } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { test } from "vitest";
import { createConnection } from "node:net";
import { createInterface } from "node:readline";
import { FIXTURE_POLICY } from "../core/fixture.js";
import { resolveSourcePolicy } from "../core/policy.js";

test("private credential bootstrap never enters public protocol, environment or diagnostics; restart refuses", async () => {
  const directory = await mkdtemp(join(tmpdir(), "mcp-bootstrap-"));
  const canary = "private-fixture-credential-329";
  const args = ["--import", "tsx", "src/research/mcp/main.ts", "--directory", directory];
  const child = spawn(process.execPath, args, { env: { PATH: process.env.PATH }, stdio: ["ignore", "pipe", "pipe", "pipe", "pipe"] });
  let stderr = ""; child.stderr!.on("data", chunk => { stderr += chunk; });
  const setup = { contractVersion: 1, sessionId: "private-session", capabilityIdentity: "private-capability", cacheNamespace: "private-trial",
    policy: FIXTURE_POLICY, limits: { calls: 1, elapsedMs: 8000, providerAttempts: 0 } };
  (child.stdio[3] as import("node:stream").Writable).end(JSON.stringify(setup));
  (child.stdio[4] as import("node:stream").Writable).end(canary);
  try {
    const lines = createInterface({ input: child.stdout! });
    const ready = await new Promise<string>((resolve, reject) => {
      lines.once("line", resolve); child.once("exit", () => reject(new Error(stderr)));
    });
    assert.equal(JSON.parse(ready).fixture, false); assert(!ready.includes(canary));
    const socket = createConnection(join(directory, "research.sock"));
    const responseLines = createInterface({ input: socket });
    const response = new Promise<string>(resolve => responseLines.once("line", resolve));
    socket.write(JSON.stringify({ jsonrpc: "2.0", id: 1, method: "initialize", params: {
      protocolVersion: "2025-11-25", capabilities: {}, clientInfo: { name: "test", version: "1" }, policy: { callLimit: 999 } } }) + "\n");
    assert(!String(await response).includes(canary)); socket.destroy();
    child.kill("SIGTERM"); await new Promise(resolve => child.once("exit", resolve));
    assert(!stderr.includes(canary));
    const restart = spawn(process.execPath, ["--import", "tsx", "src/research/mcp/main.ts", "--fixture", "--directory", directory], { env: { PATH: process.env.PATH }, stdio: ["ignore", "pipe", "pipe"] });
    let diagnostic = ""; restart.stderr.on("data", chunk => { diagnostic += chunk; });
    const status = await new Promise(resolve => restart.once("exit", resolve));
    assert.equal(status, 1); assert.match(diagnostic, /trial_already_started/);
