export const WORK_CONTRACT_VERSION = 1 as const;
export const WORK_DIMENSIONS = ["calls", "providerAttempts", "fetchedDocuments", "fetchedBytes", "scoringPairs", "scoringWindows", "scoringTokens", "elapsedMs"] as const;
