export type Work = Partial<Record<WorkDimension, number>>;
export interface WorkReservation { readonly id: string; readonly maximum: Readonly<Work>; readonly usage: Readonly<Record<WorkDimension, number | null>> }
/** Implementations must atomically reserve across ALL scopes sharing a policy allowance. */
export interface WorkLedger {
  readonly durability: "volatile" | "durable";
  limit(dimension: WorkDimension): number | null;
  reserve(id: string, maximum: Readonly<Work>, signal?: AbortSignal): Promise<WorkReservation>;
  reconcile(reservation: WorkReservation, actual: Readonly<Work>, signal?: AbortSignal): Promise<void>;
