  async reserve(id: string, maximum: Readonly<Work>): Promise<WorkReservation> {
    valid(maximum);
    if (this.reservations.has(id)) throw new ResearchError("invalid_request", "work effect already reserved; replay through its original scope");
    for (const [key, value] of Object.entries(maximum)) {
      const dimension = key as WorkDimension;
