import { ResearchEngine } from "./core/engine.js";
import { ResearchService } from "./core/service.js";
import type { CoreContext, FetchInput, FetchResult, RankedSearchResult, ResearchResult, TranscriptInput, YoutubeTranscriptResult } from "./core/contracts.js";
import type { ResearchBrokerProcess } from "./process.js";
import type { TrackedTaskStore } from "../storage/index.js";
import { resolveSourcePolicy } from "./core/policy.js";
import { researchOperationName } from "./core/contracts.js";
import type { EffectiveResearchPolicy } from "./policyCatalog.js";

export function effectiveTrialPolicy(
  policy: EffectiveResearchPolicy,
  trial: ReturnType<TrackedTaskStore["researchTrialForSession"]>
) {
  return trial?.contractVersion === 2
    ? resolveSourcePolicy(policy, trial.sourcePolicy!.profileId)
    : policy;
}

/** Canonical service and durable accounting live in the owner; network effects stay in the broker. */
export function createOwnerTrialService(store: TrackedTaskStore, broker: Pick<ResearchBrokerProcess, "executeCore">, sessionId: string, callId: string) {
  const trial = store.researchTrialForSession(sessionId)!;
  store.verifyResearchTrial(trial);
  const session = store.getInternalSessionLaunchRecord(sessionId);
  const ledger = store.researchTrialLedger(sessionId, callId);
  class BrokerEngine extends ResearchEngine {
    constructor() { super(undefined); }
    override search(context: CoreContext, input: { query: string; maxResults?: number; preferredDomains?: readonly string[] }, signal?: AbortSignal) {
      return broker.executeCore(context, { operation: "search", input }, ledger, signal) as Promise<ResearchResult<readonly RankedSearchResult[]>>;
    }
    override fetch(context: CoreContext, input: FetchInput, signal?: AbortSignal) {
      return broker.executeCore(context, { operation: "fetch", input }, ledger, signal) as Promise<ResearchResult<FetchResult>>;
    }
    override transcript(context: CoreContext, input: TranscriptInput, signal?: AbortSignal) {
      return broker.executeCore(context, { operation: "transcript", input }, ledger, signal) as Promise<ResearchResult<YoutubeTranscriptResult>>;
    }
  }
  const policy = effectiveTrialPolicy(store.resolveResearchPolicyForSession(sessionId), trial);
  return new ResearchService(new BrokerEngine(), {
    sessionId, capabilityIdentity: session.capabilityAssignment.effectiveProfileHash,
    cacheNamespace: trial.trialId, policy, callLimit: trial.limits.calls,
    ledger, signal: AbortSignal.timeout(Math.max(0, Math.min(2147483647, Date.parse(trial.deadlineAt) - Date.now()))),
    now: () => new Date(),
    authorize: async operation => Date.now() < Date.parse(trial.deadlineAt) &&
      session.capabilityAssignment.networkPolicy === "broker_only" &&
      session.capabilityAssignment.toolAllowlist.includes(researchOperationName(operation)),
    // The dispatcher atomically shapes the Pi evidence and records its compact trial result after this hook.
    record: async () => {}
  });
}
