import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { mkdtemp, open, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { createInterface } from "node:readline";
import { FIXTURE_POLICY } from "../core/fixture.js";

const directory = await mkdtemp(join(tmpdir(), "mcp-smoke-"));
const bin = dirname(fileURLToPath(import.meta.url));
const live = process.argv.slice(2).includes("--live");
const githubExcluded = process.argv.slice(2).includes("--github-excluded");
const env = { PATH: "/usr/bin:/bin" };
let credential: Awaited<ReturnType<typeof open>> | undefined;
if (live) {
  const root = process.env.CREDENTIALS_DIRECTORY;
  if (!root) throw new Error("live smoke requires systemd LoadCredentialEncrypted");
  credential = await open(join(root, "relayview-brave-search-api"), "r");
}
const sidecar = spawn(process.execPath, [join(bin, "main.js"), ...(live ? [] : ["--fixture"]), ...(githubExcluded ? ["--github-excluded"] : []), "--directory", directory],
  { env, stdio: ["ignore", "pipe", "pipe", "pipe", credential ? credential.fd : "ignore"] });
await credential?.close();
if (live) {
  const policy = githubExcluded ? { policyId: FIXTURE_POLICY.policyId, version: FIXTURE_POLICY.version,
    semanticHash: FIXTURE_POLICY.baseSemanticHash!, values: FIXTURE_POLICY.values } : FIXTURE_POLICY;
  (sidecar.stdio[3] as import("node:stream").Writable).end(JSON.stringify({ contractVersion: 1,
    sessionId: "live-smoke", capabilityIdentity: "live-smoke-v1", cacheNamespace: "live-smoke", policy,
    limits: { calls: githubExcluded ? 6 : 3, providerAttempts: 1,
      fetchedDocuments: githubExcluded ? 2 : 1, fetchedBytes: githubExcluded ? 4194304 : 2097152,
      scoringPairs: 100000, scoringWindows: 0, scoringTokens: 0, elapsedMs: githubExcluded ? 60000 : 38000 } }));
}
// Output is already allowlisted by the sidecar; retain only bounded diagnostics.
let diagnostics = "";
sidecar.stderr!.on("data", chunk => { diagnostics = (diagnostics + chunk).slice(-8192); });
let bridge: ReturnType<typeof spawn> | undefined;
let successful = false;
try {
  const readiness = createInterface({ input: sidecar.stdout! });
  const ready = await Promise.race([
    (async () => { for await (const line of readiness) return JSON.parse(line); throw new Error("sidecar_exited"); })(),
    new Promise<never>((_, reject) => { const t = setTimeout(() => reject(new Error("startup_timeout")), 10000); t.unref(); })
  ]);
  assert.equal(ready.type, "ready");
  assert.equal(ready.sourcePolicy.requestedProfileId, githubExcluded ? "github-excluded-v1" : "public-web-v1");
  assert.equal(ready.sourcePolicy.effective.profileId, ready.sourcePolicy.requestedProfileId);
  // Host networking remains outside the bridge. Hide private setup/credential mounts.
  const sandbox = ["--die-with-parent", "--unshare-net", "--unshare-pid", "--ro-bind", "/", "/", "--proc", "/proc", "--dev", "/dev", "--tmpfs", "/run", "--", process.execPath];
  const probe = spawn("bwrap", [...sandbox, "-e", "const s=require('net').connect({host:'1.1.1.1',port:443});s.on('connect',()=>process.exit(1));s.on('error',()=>process.exit(0));setTimeout(()=>process.exit(0),1000)"], { env, stdio: "ignore" });
  assert.equal(await new Promise(resolve => probe.once("exit", resolve)), 0, "direct egress must fail");
  bridge = spawn("bwrap", [...sandbox, join(bin, "bridge.js"), join(directory, "research.sock")], { env, stdio: ["pipe", "pipe", "pipe"] });
  let next = 0;
  const pending = new Map<number, { resolve(v: any): void; reject(e: Error): void }>();
  const lines = createInterface({ input: bridge.stdout! });
  lines.on("line", line => { const v = JSON.parse(line); pending.get(v.id)?.resolve(v); pending.delete(v.id); });
  bridge.once("exit", () => { for (const p of pending.values()) p.reject(new Error("bridge_disconnected")); pending.clear(); });
  const request = async (method: string, params: unknown = {}) => {
    const id = ++next;
    const response = await new Promise<any>((resolve, reject) => {
      pending.set(id, { resolve, reject });
      bridge!.stdin!.write(JSON.stringify({ jsonrpc: "2.0", id, method, params }) + "\n");
      const timer = setTimeout(() => { pending.delete(id); reject(new Error("request_timeout")); }, 20000); timer.unref();
    });
    assert(!response.error, JSON.stringify(response.error)); return response.result;
  };
  await request("initialize", { protocolVersion: "2025-11-25", capabilities: {}, clientInfo: { name: "smoke", version: "1" } });
  bridge.stdin!.write(JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }) + "\n");
  const inventory = await request("tools/list"); assert.equal(inventory.tools.length, 2);
  const call = async (name: string, args: unknown) => {
