  assert.equal(ids.length, 3);
  const continued = await call("web_fetch", { continuation: { contractVersion: 1, documentHandle: fetched.value.documentHandle, chunkIds: ids } });
  assert.equal(continued.value.selectedCount, 3); assert.equal(continued.budget.used, 3);
  let sourceDenial: unknown;
  let finalBudget = continued.budget;
  if (githubExcluded) {
    const searchDenial = await denied("web_search", { query: "upstream implementation", preferredDomains: ["github.com"] });
    const directDenial = await denied("web_fetch", { url: "https://github.com/openai/openai-node" });
