    sourceDenial = { search: searchDenial.code, directFetch: directDenial.code,
      redirectFetch: redirectDenial?.code ?? "covered_by_core_redirect_fixture", blockedContentDelivered: false };
  }
  console.log(JSON.stringify({ evidence: live ? "live_brave_search_public_fetch" : "deterministic_transport_fixture", release: ready.release,
    policy: ready.policy, sourcePolicy: ready.sourcePolicy, setupDigest: ready.setupDigest, networkDeniedInBridge: true, searchResults: search.value.length,
    documentDigest: fetched.value.documentDigest, normalizedBytes: fetched.value.normalizedBytes, initialChunks: 4, continuationChunks: 3,
    ...(sourceDenial ? { sourceDenial } : {}), budget: finalBudget }));
  successful = true;
} catch (error) { process.stderr.write(diagnostics); throw error; }
finally {
  bridge?.kill("SIGTERM"); sidecar.kill("SIGTERM");
  await new Promise<void>(resolve => { if (sidecar.exitCode !== null) resolve(); else sidecar.once("exit", () => resolve()); });
